+// Request authorization: Bearer keys from the data, three roles.
+import { AppError } from "../errors.js";
+
+const COOK_ROUTES = [
+  ["POST", /^\/recipes\/[^/]+\/cook$/],
+  ["POST", /^\/batches\/[^/]+\/waste$/],
+  ["POST", /^\/temperatures$/],
+  ["POST", /^\/stocktakes\/[^/]+\/counts$/],
+];
+
+/** The API key record named by the Authorization header; throws unauthorized. */
+export function authenticate(store, headers) {
+  const name = Object.keys(headers).find((h) => h.toLowerCase() === "authorization");
+  const m = /^Bearer (.+)$/.exec(name ? String(headers[name]) : "");
+  const found = m && (store.data.apiKeys ?? []).find((k) => k.key === m[1]);
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** Throws forbidden unless `role` may make this request. */
+export function authorize(role, method, path) {
+  if (role === "manager") return;
+  if (role === "viewer" && method === "GET" && path !== "/audit") return;
+  if (role === "cook" && method === "GET" && path !== "/audit") return;
+  if (role === "cook" && COOK_ROUTES.some(([m, re]) => m === method && re.test(path))) return;
+  throw new AppError("forbidden");
+}
